/**
 * Standardised photo-set analysis (rest + 5 movements), e.g. for
 * retrospective analytical validation on existing clinical photographs.
 * Images are processed in memory only and never stored.
 */
import { useState } from 'preact/hooks';
import { MOVEMENT_TASKS, analyzeSession, assessFrame, type FrameObservation, type TaskId } from '../../core';
import { createSessionRecord } from '../../data/records';
import { actions, useApp } from '../../data/store';
import { AppBar, Notice } from '../components/common';
import { Icon } from '../icons';
import { ISSUE_LABEL, TASK_LABEL, TASK_SHORT, WARNING_LABEL } from '../labels';
import { navigate } from '../router';
import { CaptureTracker } from '../../vision/captureTracker';

const SLOTS: TaskId[] = ['rest', ...MOVEMENT_TASKS];

interface Slot {
  url: string;
  /** The image as the detector saw it (flipped back for mirrored selfies), kept for landmark tracking. */
  src: CanvasImageSource | null;
  obs: FrameObservation | null;
  status: 'loading' | 'ok' | 'bad';
  note: string;
}

function flipped(img: HTMLImageElement): HTMLCanvasElement {
  const c = Object.assign(document.createElement('canvas'), { width: img.naturalWidth, height: img.naturalHeight });
  const ctx = c.getContext('2d')!;
  ctx.translate(c.width, 0);
  ctx.scale(-1, 1);
  ctx.drawImage(img, 0, 0);
  return c;
}

function loadImage(file: File): Promise<{ img: HTMLImageElement; url: string }> {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => resolve({ img, url });
    img.onerror = () => reject(new Error('image'));
    img.src = url;
  });
}

export function PhotoSet() {
  const { profile } = useApp();
  const [slots, setSlots] = useState<Partial<Record<TaskId, Slot>>>({});
  const [msg, setMsg] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [mirrored, setMirrored] = useState(false);
  if (!profile) return null;

  const pick = async (task: TaskId, file: File | undefined) => {
    if (!file) return;
    setError(null);
    const { img, url } = await loadImage(file);
    setSlots((s) => ({ ...s, [task]: { url, src: null, obs: null, status: 'loading', note: '분석 중…' } }));
    try {
      const { getEngine } = await import('../../vision/landmarker');
      const engine = await getEngine(setMsg);
      setMsg('');
      const obs = await engine.detectImage(img, mirrored);
      const q = assessFrame(obs);
      setSlots((s) => ({
        ...s,
        [task]: {
          url,
          src: mirrored ? flipped(img) : img,
          obs,
          status: q.ok ? 'ok' : 'bad',
          note: q.ok ? '사용 가능' : q.issues.map((i) => ISSUE_LABEL[i]).join(', '),
        },
      }));
    } catch {
      setError('얼굴 분석 엔진을 불러오지 못했습니다.');
      setSlots((s) => ({ ...s, [task]: { url, src: null, obs: null, status: 'bad', note: '분석 실패' } }));
    }
  };

  const ready = SLOTS.every((t) => slots[t]?.status === 'ok');

  const analyze = async () => {
    // Movement photos: the rest photo's landmarks tracked into each (FPA-GEOM 0.3.0); detection if that fails.
    const tk = new CaptureTracker();
    const rest = slots.rest;
    if (rest?.src && rest.obs) tk.setRef(rest.src, rest.obs);
    const obs = (t: TaskId): FrameObservation[] => {
      const sl = slots[t];
      if (!sl?.obs) return [];
      if (t === 'rest' || !sl.src) return [sl.obs];
      try {
        const gray = tk.grab(sl.src, sl.obs);
        return [gray ? tk.track({ obs: sl.obs, gray }) : sl.obs];
      } catch {
        return [sl.obs];
      }
    };
    const r = analyzeSession({
      affectedSide: profile.affectedSide,
      mode: 'photo',
      rest: obs('rest'),
      tasks: Object.fromEntries(MOVEMENT_TASKS.map((t) => [t, obs(t)])),
    });
    if (r.status === 'failed') {
      setError('안정 사진을 분석할 수 없습니다.');
      return;
    }
    const { getEngine } = await import('../../vision/landmarker');
    const engine = await getEngine();
    const rec = await createSessionRecord({ analysis: r, profile, mode: 'photo', engine: engine.info, camera: null });
    await actions.addSession(rec);
    Object.values(slots).forEach((s) => s && URL.revokeObjectURL(s.url));
    if (r.warnings.length) alert(r.warnings.map((w) => WARNING_LABEL[w.code]).join('\n'));
    navigate(`/session/${rec.id}`);
  };

  return (
    <>
      <AppBar title="사진 세트 분석" sub="연구용 · 정면 표준 사진 6장" onBack />
      <main class="main">
        <div class="card tight">
          <Notice>
            <span class="small">
              같은 거리·조명에서 정면으로 찍은 사진을 동작별로 선택하세요. 마비된 쪽은 프로필 설정(
              {profile.affectedSide === 'left' ? '왼쪽' : '오른쪽'})을 사용합니다. 사진은 저장되지 않습니다.
            </span>
          </Notice>
        </div>
        <label class="check">
          <input
            type="checkbox"
            checked={mirrored}
            disabled={Object.keys(slots).length > 0}
            onChange={(e) => setMirrored((e.target as HTMLInputElement).checked)}
          />
          <span class="small">
            <b>거울처럼 좌우 반전되어 저장된 셀카 사진입니다.</b> 휴대폰 설정에 따라 셀카가 반전 저장될 수 있습니다. 잘못 선택하면 마비 쪽이
            뒤바뀌어 분석됩니다. (사진을 고르기 전에 선택)
          </span>
        </label>
        {msg && <p class="small muted">{msg}</p>}
        {error && (
          <Notice tone="danger">
            <span class="small">{error}</span>
          </Notice>
        )}
        <div class="tiles">
          {SLOTS.map((t) => {
            const s = slots[t];
            return (
              <label class="tile" style={{ cursor: 'pointer', gap: '6px' }}>
                <span class="label">
                  {TASK_SHORT[t]} · {TASK_LABEL[t]}
                </span>
                <div
                  style={{
                    aspectRatio: '3/4',
                    borderRadius: '8px',
                    background: 'var(--grid)',
                    overflow: 'hidden',
                    display: 'grid',
                    placeItems: 'center',
                  }}
                >
                  {s ? <img src={s.url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : <Icon name="image" />}
                </div>
                <span
                  class={`xsmall ${s?.status === 'bad' ? '' : 'muted'}`}
                  style={s?.status === 'bad' ? { color: 'var(--critical)' } : {}}
                >
                  {s ? s.note : '사진 선택'}
                </span>
                <input type="file" accept="image/*" hidden onChange={(e) => pick(t, (e.target as HTMLInputElement).files?.[0])} />
              </label>
            );
          })}
        </div>
        <button class="btn primary block" disabled={!ready} onClick={analyze}>
          분석하고 저장
        </button>
      </main>
    </>
  );
}
